CREATE TABLE qard_private.ahorro_access(owner_id uuid PRIMARY KEY, pin_hash text NOT NULL, failures int NOT NULL DEFAULT 0, blocked_until timestamptz, token_hash text, expires_at timestamptz);
REVOKE ALL ON qard_private.ahorro_access FROM PUBLIC,anon,authenticated;
INSERT INTO qard_private.ahorro_access(owner_id,pin_hash) SELECT DISTINCT ON (b.titular_user_id) b.titular_user_id,a.pin_hash FROM public.qard_bolsillos b JOIN qard_private.bolsillo_access a ON a.bolsillo_id=b.id ORDER BY b.titular_user_id,b.created_at,b.id;
CREATE FUNCTION qard_private.qard_ahorro_read(_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) OR NOT EXISTS(SELECT 1 FROM qard_private.ahorro_access WHERE owner_id=auth.uid() AND expires_at>now() AND token_hash=encode(extensions.digest(_token,'sha256'),'hex')) THEN RETURN jsonb_build_object('ok',false,'error','Abre Ahorro con tu PIN'); END IF;
RETURN jsonb_build_object('ok',true,'bolsillos',coalesce((SELECT jsonb_agg(x ORDER BY x.concepto) FROM (SELECT concepto,sum(saldo_mxn) AS saldo FROM public.qard_bolsillos WHERE titular_user_id=auth.uid() GROUP BY concepto) x),'[]'::jsonb)); END $$;
CREATE FUNCTION qard_private.qard_ahorro_unlock(_pin text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a qard_private.ahorro_access; t text; r jsonb; BEGIN
IF auth.uid() IS NULL OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) OR _pin IS NULL OR _pin !~ '^(\d{4}|\d{6})$' THEN RETURN jsonb_build_object('ok',false,'error','PIN de 4 o 6 dígitos requerido'); END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'ahorro',25));
INSERT INTO qard_private.ahorro_access(owner_id,pin_hash) VALUES(auth.uid(),extensions.crypt(_pin,extensions.gen_salt('bf',10))) ON CONFLICT DO NOTHING;
SELECT * INTO a FROM qard_private.ahorro_access WHERE owner_id=auth.uid() FOR UPDATE;
IF a.blocked_until>now() THEN RETURN jsonb_build_object('ok',false,'error','Espera 15 minutos antes de volver a intentar'); END IF;
IF extensions.crypt(_pin,a.pin_hash) IS DISTINCT FROM a.pin_hash THEN
UPDATE qard_private.ahorro_access SET failures=CASE WHEN blocked_until<=now() THEN 1 ELSE failures+1 END,blocked_until=CASE WHEN (CASE WHEN blocked_until<=now() THEN 0 ELSE failures END)+1>=5 THEN now()+interval '15 minutes' ELSE NULL END,token_hash=NULL,expires_at=NULL WHERE owner_id=auth.uid(); RETURN jsonb_build_object('ok',false,'error','PIN incorrecto'); END IF;
t:=encode(extensions.gen_random_bytes(32),'hex'); UPDATE qard_private.ahorro_access SET failures=0,blocked_until=NULL,token_hash=encode(extensions.digest(t,'sha256'),'hex'),expires_at=now()+interval '5 minutes' WHERE owner_id=auth.uid(); r:=qard_private.qard_ahorro_read(t); RETURN r||jsonb_build_object('token',t); END $$;
ALTER FUNCTION qard_private.qard_bolsillo_create(uuid,text,text,numeric) RENAME TO bolsillo_create_legacy;
REVOKE ALL ON FUNCTION qard_private.bolsillo_create_legacy(uuid,text,text,numeric) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION qard_private.qard_ahorro_create(_id uuid,_concepto text,_token text,_amount numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN
IF NOT coalesce((qard_private.qard_ahorro_read(_token)->>'ok')::boolean,false) THEN RAISE EXCEPTION 'Abre Ahorro con tu PIN'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'ahorro',25));
IF EXISTS(SELECT 1 FROM public.qard_bolsillos WHERE id=_id AND titular_user_id=auth.uid() AND concepto=_concepto) THEN RETURN jsonb_build_object('ok',true,'repeated',true); END IF;
IF EXISTS(SELECT 1 FROM public.qard_bolsillos WHERE titular_user_id=auth.uid() AND concepto=_concepto) THEN RAISE EXCEPTION 'Ya existe un Bolsillo con ese concepto'; END IF;
r:=qard_private.bolsillo_create_legacy(_id,_concepto,'000000',_amount); RETURN jsonb_build_object('ok',true,'id',_id); END $$;
CREATE FUNCTION qard_private.qard_bolsillo_create(_id uuid,_concepto text,_pin text,_amount numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN r:=qard_private.qard_ahorro_unlock(_pin); IF NOT coalesce((r->>'ok')::boolean,false) THEN RETURN r; END IF; RETURN qard_private.qard_ahorro_create(_id,_concepto,r->>'token',_amount); END $$;
CREATE OR REPLACE FUNCTION qard_private.qard_bolsillo_unlock(_id uuid,_pin text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.qard_bolsillos WHERE id=_id AND titular_user_id=auth.uid()) THEN RETURN jsonb_build_object('ok',false,'error','Bolsillo no disponible'); END IF; r:=qard_private.qard_ahorro_unlock(_pin); IF coalesce((r->>'ok')::boolean,false) THEN RETURN r||jsonb_build_object('saldo',(SELECT saldo_mxn FROM public.qard_bolsillos WHERE id=_id)); END IF; RETURN r; END $$;
CREATE OR REPLACE FUNCTION qard_private.qard_bolsillo_read(_id uuid,_token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce((qard_private.qard_ahorro_read(_token)->>'ok')::boolean,false) THEN RETURN jsonb_build_object('ok',false,'error','Abre Ahorro con tu PIN'); END IF; IF NOT EXISTS(SELECT 1 FROM public.qard_bolsillos WHERE id=_id AND titular_user_id=auth.uid()) THEN RETURN jsonb_build_object('ok',false,'error','Bolsillo no disponible'); END IF; RETURN jsonb_build_object('ok',true,'saldo',(SELECT saldo_mxn FROM public.qard_bolsillos WHERE id=_id)); END $$;
CREATE FUNCTION qard_private.qard_ahorro_return(_concepto text,_token text,_amount numeric,_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.qard_bolsillos; remaining numeric:=_amount; take numeric; r jsonb; o qard_private.bolsillo_ops; first_id uuid; BEGIN
IF NOT coalesce((qard_private.qard_ahorro_read(_token)->>'ok')::boolean,false) OR _amount IS NULL OR _amount<=0 OR _amount<>round(_amount,2) OR _key IS NULL THEN RAISE EXCEPTION 'Acceso o monto inválido'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'ahorro',25));
SELECT * INTO o FROM qard_private.bolsillo_ops WHERE operation_key=_key;
IF o.operation_key IS NOT NULL THEN IF o.owner_id=auth.uid() AND o.action='group_return' AND o.amount=_amount AND o.result->>'concepto'=_concepto THEN RETURN o.result; END IF; RAISE EXCEPTION 'Operación diferente'; END IF;
PERFORM 1 FROM public.qard_wallets WHERE titular_user_id=auth.uid() FOR UPDATE;
IF (SELECT coalesce(sum(saldo_mxn),0) FROM public.qard_bolsillos WHERE titular_user_id=auth.uid() AND concepto=_concepto)<_amount THEN RAISE EXCEPTION 'Saldo insuficiente'; END IF;
FOR b IN SELECT * FROM public.qard_bolsillos WHERE titular_user_id=auth.uid() AND concepto=_concepto ORDER BY created_at,id FOR UPDATE LOOP
first_id:=coalesce(first_id,b.id); take:=least(remaining,b.saldo_mxn); IF take>0 THEN PERFORM qard_private.qard_bolsillo_return(b.id,_token,take,md5(_key::text||b.id::text)::uuid); remaining:=remaining-take; END IF; EXIT WHEN remaining=0; END LOOP;
IF remaining<>0 THEN RAISE EXCEPTION 'Saldo insuficiente'; END IF;
r:=jsonb_build_object('ok',true,'concepto',_concepto); INSERT INTO qard_private.bolsillo_ops VALUES(_key,auth.uid(),first_id,'group_return',_amount,r); RETURN r; END $$;
CREATE FUNCTION public.qard_ahorro_unlock(_pin text) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT qard_private.qard_ahorro_unlock(_pin) $$;
CREATE FUNCTION public.qard_ahorro_read(_token text) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT qard_private.qard_ahorro_read(_token) $$;
CREATE FUNCTION public.qard_ahorro_create(_id uuid,_concepto text,_token text,_amount numeric) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT qard_private.qard_ahorro_create(_id,_concepto,_token,_amount) $$;
CREATE FUNCTION public.qard_ahorro_return(_concepto text,_token text,_amount numeric,_key uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT qard_private.qard_ahorro_return(_concepto,_token,_amount,_key) $$;
REVOKE ALL ON FUNCTION qard_private.qard_ahorro_unlock(text),qard_private.qard_ahorro_read(text),qard_private.qard_ahorro_create(uuid,text,text,numeric),qard_private.qard_ahorro_return(text,text,numeric,uuid),qard_private.qard_bolsillo_create(uuid,text,text,numeric),public.qard_ahorro_unlock(text),public.qard_ahorro_read(text),public.qard_ahorro_create(uuid,text,text,numeric),public.qard_ahorro_return(text,text,numeric,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION qard_private.qard_ahorro_unlock(text),qard_private.qard_ahorro_read(text),qard_private.qard_ahorro_create(uuid,text,text,numeric),qard_private.qard_ahorro_return(text,text,numeric,uuid),qard_private.qard_bolsillo_create(uuid,text,text,numeric),public.qard_ahorro_unlock(text),public.qard_ahorro_read(text),public.qard_ahorro_create(uuid,text,text,numeric),public.qard_ahorro_return(text,text,numeric,uuid) TO authenticated;